// Get the Key "invoices/file.pdf"

var fullPath = msg.payload.Key;
var parts = fullPath.split('/');

// 1. Extract Bucket (First part)
var bucketName = parts[0]; 
var userEmail = parts[2]

// 2. Extract Key (Everything after bucket)
// This is the path MinIO needs to find the file
var key = parts.slice(1).join('/'); 

// 3. Extract Original Name (Just the last part)
// This is what the human wants to see
var originalName = parts[parts.length - 1];

msg.bucket = bucketName;
msg.filename = key;
msg.userEmail = userEmail;

msg.meta = {
    bucket: bucketName,
    key: key,             // e.g. "users/john/invoice.pdf"
    original_name: originalName // e.g. "invoice.pdf"
};

return msg;

// 1. Get the raw file buffer from S3
var fileBuffer = msg.payload;
// Convert to Base64
var base64String = fileBuffer.toString('base64');

// 2. Define the Prompt
const prompt = `
You are an expert receipt parser. Extract the following information from the provided receipt image text or .pdf files.
Return ONLY a valid JSON object. Do not include markdown formatting (like \`\`\`json).

Fields to extract:
1. "shop_name": The name of the store or vendor (e.g., "Lidl", "Sklavenitis", "Grigoris" or the fullname like, 'Λιντλ Ελλάς και Σια ΟΕ'). In general, if you are 100% of the compay's name try to find the full name like, 'Λιντλ Ελλάς και Σια ΟΕ' and do not with the company's brandname.
2. "total_amount": The final total price paid (as a number).
3. "total_tax_amount": The total VAT/Tax amount (look for "ΦΠΑ", "VAT", or "Tax" in the summary table).
4. "invoice_number": The receipt number (look for "ΑΡΙΘΜΟΣ", "No", "Ticket #").
5. "invoice_date": The date of the transaction in YYYY-MM-DD format.
6. "item_count": Calculate the total count of items bought.
   - Logic: If a line has a quantity multiplier (e.g., "2 x 1.20"), count that as 2 items.
   - Logic: If a line is measured by weight (e.g., "kg"), count it as 1 item.
   - Logic: Sum these up for the total.

Rules:
- If a value is missing, use null.
- For the date, convert formats like "07.01.26" to "2026-01-07".
- The text is likely in Greek.
`;

msg.payload = {
    contents: [
        {
            parts: [
                { text: prompt },
                {
                    inline_data: {
                        mime_type: "application/pdf",
                        data: msg.payload.toString('base64')
                    }
                }
            ]
        }
    ]
};


// 4. Set the API Endpoint
// We use the specific version "-001" which is more stable
var apiKey = "''"; 
// var model = "gemini-2.5-flash-lite";
var model = "gemini-3-pro-preview"

msg.url = "https://generativelanguage.googleapis.com/v1beta/models/" + model + ":generateContent?key=" + apiKey;

// 5. Ensure Headers are correct
msg.headers = {
    "Content-Type": "application/json"
};

return msg;

// 1. Log the full response to the console (for debugging)
// node.warn("Raw Gemini Response: " + JSON.stringify(msg.payload));

// 2. Check for Safety Blocks (Common with invoices)
if (msg.payload.promptFeedback && msg.payload.promptFeedback.blockReason) {
    node.error("Blocked by AI Safety: " + msg.payload.promptFeedback.blockReason);
    return null;
}

// 3. Check if we have candidates
if (!msg.payload.candidates || msg.payload.candidates.length === 0) {
    node.error("No candidates returned. Check the raw response.");
    return null;
}

try {
    // 4. Navigate safely to the text
    var candidate = msg.payload.candidates[0];

    // Check if the model finished successfully
    if (candidate.finishReason !== "STOP") {
        node.warn("Warning: AI finished with reason: " + candidate.finishReason);
    }

    var rawText = candidate.content.parts[0].text;

    if (!rawText) throw new Error("Text field is empty");

    // 5. Clean and Parse
    rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();
    var data = JSON.parse(rawText);

    msg.payload = data;
    return msg;

} catch (e) {
    node.error("Extraction Failed: " + e.message);
    // Pass the raw text so you can see it in Debug even if parse fails
    msg.payload = { error: e.message, rawText: rawText };
    return msg;
}

// 1. Get data safely
var ai = msg.payload || {};
var meta = msg.meta || {};

// Defaults to prevent crashes
if (!ai.shop_name && !msg.payload) ai = { shop_name: "DEBUG_ENTRY", total_amount: 0 };

// 2. Helper to escape single quotes (Crucial for SQL strings)
//    e.g. "McDonald's" becomes "McDonald''s"
const safe = (str) => {
    if (str === null || str === undefined) return "N/A";
    return str.toString().replace(/'/g, "''");
};

// 3. Prepare values
const total = parseFloat(ai.total_amount) || 0;
const tax = parseFloat(ai.total_tax_amount) || 0;
const items = parseInt(ai.item_count) || 1;
const date = (ai.invoice_date && ai.invoice_date.length === 10) ? ai.invoice_date : new Date().toISOString().split('T')[0];

// 4. Construct the RAW SQL STRING
//    We inject the values directly. This bypasses the node's parameter logic.
var sql = `INSERT INTO invoices (shop_name, invoice_number, total_amount, total_tax_amount, item_count, invoice_date, file_path, bucket_name, original_filename, user_email) VALUES ('${safe(ai.shop_name)}', '${safe(ai.invoice_number)}', ${total}, ${tax}, ${items}, '${date}', '${safe(meta.key)}', '${safe(meta.bucket)}', '${safe(meta.original_name)}', '${msg.userEmail}')`;

// 5. CRITICAL: The "Magic Wrapper" for node-red-contrib-postgresql
//    This node often requires the query to be in *every* possible slot to work.
msg.payload = sql;  // Some versions read this
msg.topic = sql;    // Some versions read this
msg.query = sql;    // Some versions read this

return msg;

