    ALTER TABLE invoices 
    ADD COLUMN IF NOT EXISTS file_path VARCHAR(255),
    ADD COLUMN IF NOT EXISTS bucket_name VARCHAR(100),
    ADD COLUMN IF NOT EXISTS original_filename VARCHAR(255);
`;
return msg;

var statusMsg = {
    payload: {
        filename: msg.meta.original_name,
        status: "File Queued. Downloading...",
        progress: 25
    }
};

return [msg, statusMsg]; // Output 1 goes to flow, Output 2 goes to WebSocket

var statusMsg = {
    payload: {
        filename: msg.meta.original_name,
        status: "Analyzing Document with AI...",
        progress: 50
    }
};

return [msg, statusMsg]; // Output 1 goes to flow, Output 2 goes to WebSocket

var statusMsg = {
    payload: {
        filename: msg.meta.original_name,
        status: "Extracting Data & Saving...",
        progress: 75
    }
};

return [msg, statusMsg]; // Output 1 goes to flow, Output 2 goes to WebSocket

var statusMsg = {
    payload: {
        filename: msg.meta.original_name,
        status: "Done",
        progress: 100
    }
};

return [msg, statusMsg]; // Output 1 goes to flow, Output 2 goes to WebSocket

// 1. Get file and convert
var fileBuffer = msg.payload;
var base64String = fileBuffer.toString('base64');

// 2. Define Prompt
const prompt = `
You are an expert receipt parser. Extract the following information from the provided receipt PDF.
Return ONLY a valid JSON object. Do not include markdown formatting.

Fields to extract:
1. "shop_name": The name of the store (e.g. "Lidl").
2. "total_amount": The final total price paid (number).
3. "total_tax_amount": The total VAT/Tax amount.
4. "invoice_number": The receipt number.
5. "invoice_date": The date in YYYY-MM-DD format.
6. "item_count": Calculate the total count of items bought.

Rules:
- If a value is missing, use null.
- Convert dates to YYYY-MM-DD.
`;

// 3. Payload for Claude 3 Sonnet (Original)
msg.payload = {
    // THIS IS THE CRITICAL CHANGE
    // We use the older Sonnet which supports PDFs but is widely accessible
    "model": "claude-3-5-sonnet-20241022", 
    "max_tokens": 2048,
    "messages": [
        {
            "role": "user",
            "content": [
                {
                    "type": "document", // Supported by Sonnet
                    "source": {
                        "type": "base64",
                        "media_type": "application/pdf",
                        "data": base64String
                    }
                },
                {
                    "type": "text",
                    "text": prompt
                }
            ]
        }
    ]
};

// 4. Headers
var apiKey = "process.env.ANTHROPIC_API_KEY || ''"; 


msg.url = "https://api.anthropic.com/v1/messages";
msg.headers = {
    "x-api-key": apiKey,
    "anthropic-version": "2023-06-01",
    "content-type": "application/json"
};

return msg;
